INSERT INTO "PreGeneratedQuestion" (id, "questionType", system, difficulty, "questionData", "questionOrder", "taskCategory", "validationStatus", "generatedAt")
VALUES
('q-tax-cv-011', 'clinical-vignette', 'CV', 'medium', '{"question":"A 35-year-old woman with no prior cardiac history presents with syncope during exertion. Her mother died suddenly at age 48. Physical exam reveals an abrupt systolic murmur that increases with Valsalva maneuver. Echocardiography shows left ventricular hypertrophy with a peak outflow gradient of 65 mmHg at rest.","options":["A. Aortic stenosis","B. Hypertrophic cardiomyopathy (HCM)","C. Dilated cardiomyopathy","D. Mitral regurgitation"],"correctAnswer":"B","correctAnswerIndex":0,"explanation":"This is classic HCM: young patient with exertional syncope, family history of sudden cardiac death, systolic murmur that increases with Valsalva (decreases with leg-raising or squatting), and LV hypertrophy with dynamic outflow obstruction on echo. HCM is the leading cause of sudden death in young athletes. Option A (aortic stenosis) has a murmur that decreases with Valsalva and does not increase with Valsalva maneuver. Option C (DCM) presents with dilated ventricles and low EF. Option D (MR) has a holosystolic murmur without the dynamic characteristics.","conditionName":"Hypertrophic Cardiomyopathy","system":"CV","subcategory":"Cardiomyopathy","tags":["CV","HCM","sudden-death","cardiomyopathy","outflow-obstruction"],"generatedWith":"taxonomy-gen-v1"}', 'second', 'history_pe', 'pending', NOW()),
('q-tax-cv-012', 'clinical-vignette', 'CV', 'medium', '{"question":"A 70-year-old man with chronic kidney disease (creatinine 2.8 mg/dL) presents with progressive dyspnea and lower extremity edema. Echocardiography shows EF 25% with diffuse hypokinesis. He is already on lisinopril, metoprolol, and furosemide. BNP is 850 pg/mL. Which medication should be added next?","options":["A. Aldosterone antagonist (spironolactone)","B. Digoxin","C. Hydralazine + nitrate combination","D. Calcium channel blocker (diltiazem)"],"correctAnswer":"A","correctAnswerIndex":0,"explanation":"In systolic heart failure, aldosterone antagonists (spironolactone/eplerenone) improve survival and are indicated when EF <35%. This patient is on an ACE inhibitor and beta-blocker but not on an aldosterone antagonist. Must check potassium and renal function before starting, but even with CKD (Cr 2.8), cautious use with monitoring is appropriate. Option B (digoxin): improves symptoms but does not improve survival in HF. Option C (hydralazine + nitrate): reserved for African Americans or those intolerant to ACE-I/ARB. Option D (calcium channel blockers): generally avoided in systolic HF as they are negatively inotropic.","conditionName":"Chronic Systolic Heart Failure - Advanced","system":"CV","subcategory":"Heart Failure","tags":["CV","HF","aldosterone-antagonist","reduced-EF","CKD"],"generatedWith":"taxonomy-gen-v1"}', 'second', 'pharmaceutical', 'pending', NOW()),
('q-tax-cv-013', 'clinical-vignette', 'CV', 'medium', '{"question":"A 48-year-old male with a history of MI 3 years ago presents with a 2-week history of progressive dyspnea, orthopnea, and PND. Exam shows bilateral crackles and a displaced PMI. EF is now 30% (previously 35%). Given his optimal medical therapy (ACE-I, beta-blocker, aldosterone antagonist), what intervention is most likely to improve survival?","options":["A. Inotropic support with milrinone infusion","B. Cardiac resynchronization therapy (CRT) if QRS >120 ms","C. Increased diuretic dosing only","D. Bed rest and dietary sodium restriction"],"correctAnswer":"B","correctAnswerIndex":0,"explanation":"This patient has advanced systolic HF (EF 30%) with worsening symptoms despite optimal medical therapy. Cardiac resynchronization therapy (CRT), an implantable device that paces both ventricles to improve synchrony, has proven mortality benefit in systolic HF when EF ≤35% and QRS ≥120 ms. This patient appears to be a CRT candidate. Option A (milrinone): inotropic support does NOT improve long-term survival and may worsen outcomes with chronic use. Option C & D: diuretics and lifestyle measures manage symptoms but do not alter survival trajectory. CRT is the next indicated intervention.","conditionName":"Advanced Systolic HF - Device Therapy","system":"CV","subcategory":"Heart Failure","tags":["CV","heart-failure","CRT","device-therapy","QRS"],"generatedWith":"taxonomy-gen-v1"}', 'second', 'management', 'pending', NOW()),
('q-tax-cv-014', 'clinical-vignette', 'CV', 'medium', '{"question":"A 62-year-old man with diabetes and hypertension develops sudden acute shortness of breath at rest. Vital signs: BP 155/95, HR 118, RR 28, O2 sat 88% on room air. Lung sounds reveal fine crackles bilaterally. BNP 950 pg/mL. Echocardiography shows EF 55% with normal systolic function but severely impaired diastolic filling.","options":["A. Acute systolic heart failure","B. Acute diastolic (HFpEF) decompensation","C. Acute respiratory distress syndrome","D. Pneumonia with sepsis"],"correctAnswer":"B","correctAnswerIndex":0,"explanation":"This is acute heart failure with preserved EF (HFpEF): preserved systolic function (EF 55%) but impaired diastolic filling, presenting with acute pulmonary edema. HFpEF is common in elderly patients with hypertension and diabetes. The elevated BNP, crackles, dyspnea, and echo findings are diagnostic. Option A specifies systolic dysfunction which is not present here. Option C & D: while pulmonary edema is present, the echo showing preserved EF and diastolic dysfunction points to HFpEF. Management focuses on diuretics, BP control, and rate control (unlike systolic HF which requires ACE-I/beta-blockers).","conditionName":"Heart Failure with Preserved EF","system":"CV","subcategory":"Heart Failure","tags":["CV","HFpEF","diastolic-HF","preserved-EF"],"generatedWith":"taxonomy-gen-v1"}', 'second', 'diagnostics', 'pending', NOW()),
('q-tax-cv-015', 'clinical-vignette', 'CV', 'medium', '{"question":"A 74-year-old man with chronic atrial fibrillation (on metoprolol and warfarin) presents with acute onset right leg swelling and pain. Vital signs are stable. D-dimer is elevated. Compression ultrasound shows absence of normal compressibility in the left femoral vein. What is the next appropriate management?","options":["A. Continue warfarin; arrange for repeat ultrasound in 1 week","B. Maintain current anticoagulation and refer to vascular surgery for embolectomy","C. Stop warfarin; initiate heparin, then transition to apixaban when INR is subtherapeutic","D. Initiate thrombolytic therapy immediately"],"correctAnswer":"B","correctAnswerIndex":0,"explanation":"This patient has acute DVT (venous incompressibility on ultrasound) with ongoing anticoagulation (warfarin). Assuming his INR is therapeutic, the current anticoagulation is appropriate for uncomplicated DVT. Compression ultrasonography confirms the diagnosis. Option A: inadequate—he needs active anticoagulation management. Option C: switching anticoagulants is unnecessary unless warfarin is subtherapeutic or contraindicated. Option D: thrombolytics are reserved for massive PE or phlegmasia cerulea dolens (limb-threatening). Standard management is therapeutic anticoagulation; vascular surgery consultation is for complications or massive DVT with hemodynamic compromise.","conditionName":"Deep Vein Thrombosis","system":"CV","subcategory":"Venous Thromboembolism","tags":["CV","DVT","anticoagulation","ultrasound"],"generatedWith":"taxonomy-gen-v1"}', 'second', 'diagnostics', 'pending', NOW()),
('q-tax-cv-016', 'clinical-vignette', 'CV', 'medium', '{"question":"A 58-year-old male with a 40-pack-year smoking history presents with claudication in his left calf after walking 200 feet. He has diminished femoral pulses and cool left foot compared to right. Ankle-brachial index (ABI) is 0.6 on the left. Which of the following represents the MOST critical next step in management?","options":["A. Immediately refer for amputation evaluation","B. Start aspirin, statin, ACE inhibitor, and initiate supervised walking program","C. Obtain CT angiography of the aorta and lower extremities","D. Refer urgently for percutaneous angioplasty"],"correctAnswer":"B","correctAnswerIndex":0,"explanation":"This patient has symptomatic peripheral arterial disease (PAD) Stage II claudication (ABI 0.4-0.9). Management priorities: (1) Cardiovascular risk factor modification: dual antiplatelet therapy (aspirin ± clopidogrel), statin, ACE inhibitor, blood pressure control, smoking cessation, (2) Supervised exercise program (proven to improve claudication distance). Imaging (CT angiography or vascular ultrasound) is done after initial medical optimization and when symptoms persist. Option A: amputation is reserved for critical limb ischemia with tissue loss or gangrene, not uncomplicated claudication. Option D: revascularization (angioplasty or surgery) is considered if medical therapy + exercise fails or if critical ischemia develops.","conditionName":"Peripheral Arterial Disease","system":"CV","subcategory":"PAD","tags":["CV","PAD","claudication","ABI","smoking"],"generatedWith":"taxonomy-gen-v1"}', 'second', 'health_maintenance', 'pending', NOW()),
('q-tax-cv-017', 'clinical-vignette', 'CV', 'medium', '{"question":"A 52-year-old woman with no prior cardiac history presents with sudden dyspnea, tachycardia (120 bpm), hypotension (90/60), and severe right-sided chest pain. Examination reveals muffled heart sounds and elevated JVP. Echocardiography shows a large pericardial effusion with right atrial and ventricular collapse. What is the immediate management?","options":["A. Administer diuretics and observe for spontaneous resolution","B. Emergent pericardiocentesis with simultaneous vasopressor support","C. Arrange for chest CT to confirm diagnosis","D. Admit to ICU for monitoring without intervention"],"correctAnswer":"B","correctAnswerIndex":0,"explanation":"This is cardiac tamponade: pericardial effusion causing hemodynamic compromise (hypotension, elevated JVP, muffled heart sounds, tachycardia) with echo findings of RV/RA collapse. This is a medical emergency requiring immediate decompression. Option B is correct: emergent pericardiocentesis (needle or surgical drainage) to relieve tamponade, combined with IV fluids and vasopressors to maintain perfusion. Option A (diuretics): contraindicated—these worsen tamponade by decreasing preload. Option C: imaging delays life-saving intervention. Option D: observation without intervention is lethal; tamponade requires urgent decompression.","conditionName":"Cardiac Tamponade","system":"CV","subcategory":"Pericardial Disease","tags":["CV","tamponade","pericardial-effusion","emergency"],"generatedWith":"taxonomy-gen-v1"}', 'second', 'management', 'pending', NOW()),
('q-tax-cv-018', 'clinical-vignette', 'CV', 'hard', '{"question":"A 64-year-old man with history of hypertension is found to have a systolic murmur (grade 3/6) heard best at the right upper sternal border that radiates to the carotids. Carotid pulses are diminished and delayed. He denies dyspnea but reports mild exertional chest discomfort. What is the most likely diagnosis and what finding would confirm it?","options":["A. Aortic regurgitation; wide pulse pressure","B. Aortic stenosis; narrowed pulse pressure","C. Mitral regurgitation; laterally displaced PMI","D. Pulmonary hypertension; elevated JVP"],"correctAnswer":"B","correctAnswerIndex":0,"explanation":"Classic aortic stenosis (AS): systolic murmur at right sternal border radiating to carotids, diminished/delayed (pulsus parvus et tardus) carotid pulses, and exertional chest discomfort. AS causes a narrowed pulse pressure (systolic minus diastolic) due to reduced cardiac output and increased peripheral resistance. Option A (aortic regurgitation): produces a wide pulse pressure with bounding pulses and early diastolic murmur. Option C (mitral regurgitation): pansystolic murmur at apex radiating to axilla. Option D: pulmonary hypertension does not produce these murmur characteristics. Echocardiography confirms AS and quantifies severity.","conditionName":"Aortic Stenosis","system":"CV","subcategory":"Valvular Disease","tags":["CV","AS","aortic-stenosis","murmur","carotid-pulse"],"generatedWith":"taxonomy-gen-v1"}', 'second', 'history_pe', 'pending', NOW()),
('q-tax-cv-019', 'clinical-vignette', 'CV', 'hard', '{"question":"A 70-year-old man with aortic regurgitation (AR) presents with progressive dyspnea. His BP is 165/45 (wide pulse pressure). Echocardiography shows severe AR with an EF of 45% (previously 65% two years ago). Left ventricular internal dimension is 62 mm (normal <55 mm). What is the most appropriate next step in management?","options":["A. Initiate ACE inhibitors; schedule follow-up echo in 6 months","B. Urgent surgical aortic valve replacement","C. Add beta-blocker to slow heart rate and decrease dP/dt","D. Start diuretics and monitor for symptom progression"],"correctAnswer":"B","correctAnswerIndex":0,"explanation":"Severe AR with LV dysfunction (EF decline from 65% to 45%), LV enlargement (LVID 62 mm), and new symptoms is an indication for urgent aortic valve replacement. Delaying surgery risks irreversible LV damage and cardiomyopathy. Option A: medical management alone is insufficient for severe AR with systolic dysfunction. Option C: beta-blockers can be used to slow dP/dt in acute AR, but this patient needs definitive surgical correction. Option D: diuretics manage symptoms but do not address the primary valvular pathology. This patient is now in a window where surgery can prevent or reverse LV dysfunction.","conditionName":"Severe Aortic Regurgitation","system":"CV","subcategory":"Valvular Disease","tags":["CV","AR","aortic-regurgitation","valve-replacement","LV-dysfunction"],"generatedWith":"taxonomy-gen-v1"}', 'second', 'management', 'pending', NOW()),
('q-tax-cv-020', 'clinical-vignette', 'CV', 'hard', '{"question":"A 42-year-old previously healthy man presents with fatigue and dyspnea on exertion for 6 weeks. Examination reveals cardiomegaly and a prominent S3 gallop. EF is 25%. Viral serologies are negative. Endomyocardial biopsy shows myocyte necrosis and mononuclear infiltration. What is the most likely diagnosis?","options":["A. Ischemic cardiomyopathy","B. Acute myocarditis","C. Dilated cardiomyopathy (idiopathic)","D. Restrictive cardiomyopathy"],"correctAnswer":"B","correctAnswerIndex":0,"explanation":"This is acute myocarditis: subacute presentation (6 weeks) with systemic symptoms (fatigue), dyspnea, cardiomegaly, S3 gallop, significantly reduced EF (25%), and diagnostic biopsy findings (myocyte necrosis + mononuclear infiltration indicating inflammatory cardiomyopathy). Negative viral serology does not rule out prior viral myocarditis. Option A (ischemic CM): would have history of MI or CAD. Option C (idiopathic DCM): also presents similarly but biopsy findings of active inflammation point to myocarditis. Option D (restrictive CM): presents with restrictive physiology (preserved EF, restrictive filling pattern) not this degree of systolic dysfunction. Myocarditis can progress to dilated CM if not treated.","conditionName":"Acute Myocarditis","system":"CV","subcategory":"Cardiomyopathy","tags":["CV","myocarditis","inflammatory","biopsy","dilated-CM"],"generatedWith":"taxonomy-gen-v1"}', 'second', 'diagnostics', 'pending', NOW());